+            lastHyphen = false;
+        } else if (c == '-' && !lastHyphen && outIdx > 0) {
+            _appName[outIdx++] = c;
+            lastHyphen = true;
+        }
+    }
+    while (outIdx > 0 && _appName[outIdx - 1] == '-') {
+        outIdx--;
+    }
+    _appName[outIdx] = '\0';
+}
